/**
 * Writes one stories file per gallery family, one story per example.
 * Run after adding an example to `apps/demo/src/library.ts`:
 *   npm run stories -w @futurcharts/storybook
 * (Storybook reads story names from the source, so they are written out here.)
 */
import { mkdirSync, readdirSync, rmSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { GROUPS, entries } from '../../demo/src/library';

const dir = fileURLToPath(new URL('../stories/', import.meta.url));
mkdirSync(dir, { recursive: true });
// Only the generated files (numbered); hand-written stories stay.
for (const f of readdirSync(dir)) if (/^\d\d-.*\.stories\.ts$/.test(f)) rmSync(dir + f);

const ascii = (s: string) => s.normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[’']/g, ' ');
const slug = (s: string) => ascii(s).toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');
const ident = (s: string) => {
  const id = ascii(s).replace(/[^A-Za-z0-9]+/g, ' ').trim().split(' ').map((w) => w[0].toUpperCase() + w.slice(1)).join('');
  return /^[0-9]/.test(id) ? `N${id}` : id;
};
const q = (s: string) => JSON.stringify(s);

let total = 0;
GROUPS.forEach(([family, titles], k) => {
  const used = new Set<string>();
  const stories = titles
    .filter((t) => entries.some((e) => e.title === t))
    .map((t) => {
      let id = ident(t);
      while (used.has(id)) id += '2';
      used.add(id);
      total++;
      return `export const ${id}: StoryObj = { name: ${q(t)}, ...entryStory(${q(t)}) };`;
    });
  const file = `// Generated by scripts/generate.ts from the gallery examples: do not edit by hand.
import type { Meta, StoryObj } from '@storybook/html';
import { entryStory } from '../story';

const meta: Meta = {
  title: ${q(`Graphiques/${family}`)},
  tags: ['autodocs'],
};
export default meta;

${stories.join('\n')}
`;
  writeFileSync(`${dir}${String(k + 1).padStart(2, '0')}-${slug(family)}.stories.ts`, file);
});
console.log(`${GROUPS.length} familles, ${total} stories.`);
